const input = require("fs").readFileSync(0, "utf8");

function uniquePaths(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  // paths[r][c] is the number of paths from the start to cell (r, c).
  const paths = Array.from({ length: rows }, () => new Array(cols).fill(0));
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === "#") {
        continue;
      }
      if (r === 0 && c === 0) {
        paths[r][c] = 1;
        continue;
      }
      const fromAbove = r > 0 ? paths[r - 1][c] : 0;
      const fromLeft = c > 0 ? paths[r][c - 1] : 0;
      paths[r][c] = fromAbove + fromLeft;
    }
  }
  return paths[rows - 1][cols - 1];
}

const lines = input.trim().split("\n");
const rows = Number(lines[0].split(" ")[0]);
const grid = lines.slice(1, 1 + rows).map((line) => line.trim().split(""));
