package main

import (
	"bufio"
	"fmt"
	"os"
)

func uniquePaths(grid []string) int {
	rows, cols := len(grid), len(grid[0])
	// paths[r][c] is the number of paths from the start to cell (r, c).
	paths := make([][]int, rows)
	for r := range paths {
		paths[r] = make([]int, cols)
	}
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if grid[r][c] == '#' {
				continue
			}
			if r == 0 && c == 0 {
				paths[r][c] = 1
				continue
			}
			if r > 0 {
				paths[r][c] += paths[r-1][c]
			}
			if c > 0 {
				paths[r][c] += paths[r][c-1]
			}
		}
	}
	return paths[rows-1][cols-1]
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var rows, cols int
	fmt.Fscan(reader, &rows, &cols)
	grid := make([]string, rows)
	for row := range grid {
		fmt.Fscan(reader, &grid[row])
	}
	fmt.Println(uniquePaths(grid))
}

