import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function uniquePaths(grid: string[][]): number {
  // paths[r][c] is the number of paths from the start to cell (r, c).
  const paths: number[][] = grid.map((line) => new Array<number>(line.length).fill(0));
  for (const [r, line] of grid.entries()) {
    const row = paths[r] ?? [];
    // Above the top row and left of the first column, the lookups give
    // undefined, which counts as no paths.
    const above = paths[r - 1] ?? [];
    for (const [c, cell] of line.entries()) {
      if (cell === "#") {
        continue;
      }
      if (r === 0 && c === 0) {
        row[c] = 1;
        continue;
      }
      row[c] = (above[c] ?? 0) + (row[c - 1] ?? 0);
    }
  }
  const lastRow = paths[paths.length - 1] ?? [];
  return lastRow[lastRow.length - 1] ?? 0;
}

const lines = input.trim().split("\n");
const rows = Number(lines[0]?.split(" ")[0] ?? 0);
const grid = lines.slice(1, 1 + rows).map((line) => line.trim().split(""));
console.log(uniquePaths(grid));
